('0d3e0000-0000-4000-8000-000000000101', null, 'About the school', 'about', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Demo School opened in 1964 as a day school for 120 students. Boarding began in 1978, and A-level in 1985."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Today the school teaches 1,150 students from senior one to senior six on a twelve-acre site in Ntinda."}]}]}'::jsonb, 'Demo School opened in 1964 as a day school for 120 students. Boarding began in 1978, and A-level in 1985. Today the school teaches 1,150 students from senior one to senior six on a twelve-acre site in Ntinda.', 'How the school started and how it runs today.', 'about', true, 1, 'published', now() - interval '1 day', now() - interval '1 day'),
('0d3e0000-0000-4000-8000-000000000102', null, 'Admissions', 'admissions', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Senior one and senior five intakes open in October. Families visit first, then apply online or on paper at the school office."}]}]}'::jsonb, 'Senior one and senior five intakes open in October. Families visit first, then apply online or on paper at the school office.', 'Intakes, visits and how to apply.', 'admissions_info', true, 3, 'published', now() - interval '1 day', now() - interval '1 day'),
('0d3e0000-0000-4000-8000-000000000103', '0d3e0000-0000-4000-8000-000000000101', 'History', 'history', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "The school was founded in 1964 by a group of parents in Ntinda who wanted a secondary school within walking distance of home."}]}]}'::jsonb, 'The school was founded in 1964 by a group of parents in Ntinda who wanted a secondary school within walking distance of home.', 'From a day school of 120 students in 1964 to today.', null, true, 1, 'published', now() - interval '1 day', now() - interval '1 day'),
('0d3e0000-0000-4000-8000-000000000104', '0d3e0000-0000-4000-8000-000000000101', 'Leadership', 'leadership', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "The school is led by the head teacher, two deputies and the board of governors, which meets once a term."}]}]}'::jsonb, 'The school is led by the head teacher, two deputies and the board of governors, which meets once a term.', 'The head teacher, deputies and board of governors.', null, true, 2, 'published', now() - interval '1 day', now() - interval '1 day');
